mapper.sql:
WHERE CONECT_ID = #{uniqId}

  AND CREAT_DT BETWEEN TO_TIMESTAMP(#{vo.searchBgnDe} || ' 00:00:00', 'YYYY-MM-DD HH24:MI:SS')
                   AND TO_TIMESTAMP(#{vo.searchEndDe} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')

mapper.select:
SELECT MBER_NM AS "name", MBER_EMAIL_ADRES AS "email", MBTLNUM AS "mbtlnum"
  FROM COMTNGNRLMBER
 WHERE ESNTL_ID = #{uniqId}

SELECT USER_NM AS "name", EMAIL_ADRES AS "email", MBTLNUM AS "mbtlnum"
  FROM COMTNEMPLYRINFO
 WHERE ESNTL_ID = #{uniqId}

mapper.update:
UPDATE COMTNGNRLMBER
   SET MBER_EMAIL_ADRES = #{email},
       MBTLNUM = #{mbtlnum}
 WHERE ESNTL_ID = #{uniqId}

UPDATE COMTNEMPLYRINFO
   SET EMAIL_ADRES = #{email},
       MBTLNUM = #{mbtlnum}
 WHERE ESNTL_ID = #{uniqId}
